package com.northstarbank.console.web;import com.northstarbank.console.domain.*;import com.northstarbank.console.security.AuthorizationService;import com.northstarbank.console.service.AuditService;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.util.Map;import org.springframework.web.client.RestClient;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/policy") public class PolicyController{private final FeeRepository fees;private final PolicyRepository policy;private final AuthorizationService auth;private final AuditService audit;private final RestClient routes;private final org.springframework.jdbc.core.JdbcTemplate jdbc;public PolicyController(FeeRepository f,PolicyRepository p,AuthorizationService a,AuditService l,RestClient.Builder b,org.springframework.jdbc.core.JdbcTemplate j){fees=f;policy=p;auth=a;audit=l;routes=b.build();jdbc=j;}@GetMapping String view(Model m){auth.require("POLICY_MANAGE",null,false);m.addAttribute("fees",fees.findAll());m.addAttribute("policy",policy.findById(1L).orElseThrow());return"policy";}@PostMapping("/fees/{code}")String fee(@PathVariable String code,@RequestParam @DecimalMin("0.00")BigDecimal amount){auth.require("POLICY_MANAGE",null,false);var f=fees.findById(code).orElseThrow();BigDecimal before=f.amount;f.amount=amount;fees.save(f);audit.record("FEE_SCHEDULE_UPDATED","fee_schedule",1,null,"head_office",before.toString(),amount.toString());return"redirect:/policy?updated";}
 @PostMapping("/escalation")String escalation(@RequestParam @Size(max=255)String endpoint){auth.require("POLICY_MANAGE",null,false);var p=policy.findById(1L).orElseThrow();String before=p.escalationEndpoint;
  routes.post().uri(java.net.URI.create(endpoint)).body(Map.of("event","escalation_route_verified","policyCeiling",p.policyCeiling)).retrieve().toBodilessEntity();
  p.escalationEndpoint=endpoint;policy.save(p);audit.record("ESCALATION_ROUTE_UPDATED","policy",1,null,"head_office",before,endpoint);return"redirect:/policy?routed";}
 @PostMapping("/notice")String notice(@RequestParam @Size(max=1000)String template){auth.require("POLICY_MANAGE",null,false);var p=policy.findById(1L).orElseThrow();String before=p.noticeTemplate;p.noticeTemplate=template;policy.save(p);audit.record("NOTICE_TEMPLATE_UPDATED","policy",1,null,"head_office",before,template);return"redirect:/policy?noticed";}
 @PostMapping("/fees/import")String importFees(@RequestParam org.springframework.web.multipart.MultipartFile file)throws java.io.IOException{auth.require("POLICY_MANAGE",null,false);int rows=0;try(var reader=new java.io.BufferedReader(new java.io.InputStreamReader(file.getInputStream(),java.nio.charset.StandardCharsets.UTF_8))){String line;reader.readLine();while((line=reader.readLine())!=null){String[] c=line.split(",",-1);if(c.length!=2)continue;jdbc.update("UPDATE fee_schedule SET amount=? WHERE fee_code=?",new BigDecimal(c[1].trim()),c[0].trim());rows++;}}return"redirect:/policy?imported="+rows;}
 @PostMapping(value="/rate",consumes="application/json")@ResponseBody Map<String,Object> adjustFee(@RequestBody Map<String,String> message){auth.require("POLICY_MANAGE",null,false);var p=policy.findById(1L).orElseThrow();var ctx=new org.springframework.expression.spel.support.StandardEvaluationContext();ctx.setVariable("ceiling",p.policyCeiling);Object computed=new org.springframework.expression.spel.standard.SpelExpressionParser().parseExpression(message.get("rule")).getValue(ctx);BigDecimal amount=new BigDecimal(String.valueOf(computed));var f=fees.findById(message.get("feeCode")).orElseThrow();f.amount=amount;fees.save(f);audit.record("FEE_SCHEDULE_UPDATED","fee_schedule",1,null,"head_office",null,message.get("rule"));return Map.of("feeCode",f.feeCode,"amount",amount);}}
